INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > IT-Sicherheit > Bedrohungsszenarien > Bedrohungserkennung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Bedrohungserkennung immer in der Lage, alle Sicherheitsvorfälle sofort zu identifizieren?', 2, '[{"text": "Nein", "correct": true, "because": "Erkennung kann durch neue oder versteckte Bedrohungen eingeschränkt sein"}, {"text": "Ja", "correct": false, "because": "Keine Garantie für sofortige Erkennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Bedrohungserkennung ohne spezielle Softwaretools erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Manuelle Überwachung ist möglich, aber weniger effizient"}, {"text": "Nein", "correct": false, "because": "Tools sind nicht zwingend, aber hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Bedrohungserkennung immer in Echtzeit erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch nachträgliche Analysen sind nützlich"}, {"text": "Ja", "correct": false, "because": "Echtzeit ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Bedrohungserkennungssysteme durch falsch-positive Meldungen beeinträchtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Falsch-positive Alarme können die Effizienz mindern"}, {"text": "Nein", "correct": false, "because": "Problem ist bekannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Bedrohungserkennung ausschließlich auf externe Angriffe beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Bedrohungen können erkannt werden"}, {"text": "Ja", "correct": false, "because": "Interne Bedrohungen sind relevant"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird am häufigsten für die Bedrohungserkennung in Netzwerken eingesetzt?', 2, '[{"text": "Intrusion Detection System (IDS)", "correct": true, "because": "Erkennt unbefugte Zugriffe"}, {"text": "Firewall", "correct": false, "because": "Schützt, erkennt nicht primär"}, {"text": "Antivirus", "correct": false, "because": "Fokussiert auf Endgeräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Bedrohungserkennung primär?', 3, '[{"text": "Identifizierung von Sicherheitsvorfällen", "correct": true, "because": "Früherkennung ist zentral"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Anderes Sicherheitsziel"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Aufgabe der Autorisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode verbessert die Bedrohungserkennung am effektivsten?', 2, '[{"text": "Verhaltensanalyse", "correct": true, "because": "Erkennt Anomalien im Nutzerverhalten"}, {"text": "Manuelle Überprüfung", "correct": false, "because": "Weniger effizient"}, {"text": "Passwortänderung", "correct": false, "because": "Schutz, nicht Erkennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schwäche haben viele Bedrohungserkennungssysteme?', 2, '[{"text": "Falsch-positive Meldungen", "correct": true, "because": "Kann zu Alarmmüdigkeit führen"}, {"text": "Langsame Verarbeitung", "correct": false, "because": "Nicht primäres Problem"}, {"text": "Geringer Speicherbedarf", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System kombiniert Erkennung und Abwehr von Bedrohungen?', 2, '[{"text": "Intrusion Prevention System (IPS)", "correct": true, "because": "Erkennt und blockiert aktiv"}, {"text": "Antivirus", "correct": false, "because": "Nur Endgeräteschutz"}, {"text": "Router", "correct": false, "because": "Netzwerkgerät"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Technologien werden für die Bedrohungserkennung eingesetzt?', 4, '[{"text": "Intrusion Detection System (IDS)", "correct": true, "because": "Erkennt Anomalien"}, {"text": "Security Information and Event Management (SIEM)", "correct": true, "because": "Analysiert Logs"}, {"text": "Verhaltensanalyse", "correct": true, "because": "Erkennt Abweichungen"}, {"text": "Texteditor", "correct": false, "because": "Kein Sicherheitstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen können durch Bedrohungserkennung identifiziert werden?', 3, '[{"text": "Malware", "correct": true, "because": "Erkennbar durch Signaturen"}, {"text": "Phishing", "correct": true, "because": "Durch Verhaltensmuster"}, {"text": "Insider-Bedrohungen", "correct": true, "because": "Anomalien im Zugriff"}, {"text": "Langsame Netzwerke", "correct": false, "because": "Kein Sicherheitsproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Bedrohungserkennung?', 4, '[{"text": "Früherkennung", "correct": true, "because": "Minimiert Schadenspotenzial"}, {"text": "Verbesserte Reaktion", "correct": true, "because": "Ermöglicht schnelle Maßnahmen"}, {"text": "Präventiver Schutz", "correct": true, "because": "Identifiziert Risiken"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Bedrohungserkennung?', 3, '[{"text": "Falsch-positive Meldungen", "correct": true, "because": "Vermindern Vertrauen"}, {"text": "Komplexität der Analyse", "correct": true, "because": "Erfordert Expertise"}, {"text": "Erkennung neuer Bedrohungen", "correct": true, "because": "Unbekannte Angriffe schwer"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verbessern die Bedrohungserkennung?', 3, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Hält Signaturen aktuell"}, {"text": "Schulung des Personals", "correct": true, "because": "Verbessert Reaktion"}, {"text": "Kombination von Tools", "correct": true, "because": "Erhöht Abdeckung"}, {"text": "Weniger Überwachung", "correct": false, "because": "Schwächt Erkennung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Bedrohungserkennung identifiziert Sicherheitsvorfälle. b) Sie kann alle Bedrohungen sofort erkennen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identifikation ja, sofort nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verhaltensanalyse verbessert die Bedrohungserkennung. b) Sie erfordert keine Tools.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Analyse ja, Tools hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) IDS kann Bedrohungen im Netzwerk erkennen. b) Bedrohungserkennung ist nur für externe Angriffe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IDS ja, interne Bedrohungen auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Falsch-positive Meldungen sind eine Herausforderung. b) Bedrohungserkennung muss immer in Echtzeit sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Falsch-positive ja, Echtzeit optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) SIEM-Systeme analysieren Logs zur Bedrohungserkennung. b) Sie machen andere Tools überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Log-Analyse ja, Ergänzung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

